questionvariables.text:
/* Design: classify points as on an axis or a coordinate plane; fixed category order, the correct category's position varies by item. No point is on the x-axis, so the first category is never correct. Source: original. */
plist: [[[0,0,6],[5,2,-4],[0,7,0],[-2,0,7]],[[3,8,0],[0,0,-6],[-4,3,7],[0,-3,0]],[[-6,0,5],[2,1,0],[0,0,5],[0,4,1]],[[0,-4,0],[0,0,6],[5,6,0],[-1,3,4]],[[4,7,0],[0,-3,-3],[7,0,-3],[0,-5,0]],[[2,-2,0],[3,2,-5],[0,2,5],[1,0,5]],[[4,0,-5],[-1,6,2],[0,2,0],[-5,-5,0]],[[0,0,-6],[4,-7,4],[-3,0,-5],[6,4,0]],[[-4,0,-3],[7,-5,0],[0,0,4],[0,-4,-5]],[[0,0,3],[-7,7,6],[0,-5,0],[0,5,-5]]];
ix: 1+rand(10);
pts: plist[ix];
/* category index: 1 x-axis, 2 y-axis, 3 z-axis, 4 xy-plane, 5 yz-plane, 6 xz-plane, 7 none */
cat(p) := if p[1]=0 and p[3]=0 then 2 elseif p[1]=0 and p[2]=0 then 3 elseif p[3]=0 then 4 elseif p[1]=0 then 5 elseif p[2]=0 then 6 else 7;
/* named error: z = 0 read as on the z-axis, and so on */
dgof: [1, 6, 4, 3, 1, 2, 4];
cs: map(cat, pts);
p1: pts[1]; c1: cs[1]; g1: dgof[c1];
opt1: [["xax1", is(cs[1]=1), "on the x-axis"], ["yax1", is(cs[1]=2), "on the y-axis"], ["zax1", is(cs[1]=3), "on the z-axis"], ["xy1", is(cs[1]=4), "in the xy-plane, not on an axis"], ["yz1", is(cs[1]=5), "in the yz-plane, not on an axis"], ["xz1", is(cs[1]=6), "in the xz-plane, not on an axis"], ["none1", is(cs[1]=7), "in no coordinate plane"]];
ta1: first(mcq_correct(opt1)); dg1: opt1[g1][1];
gw1: if c1 = 7 or g1 = 7 then opt1[5][1] else opt1[7][1];
p2: pts[2]; c2: cs[2]; g2: dgof[c2];
opt2: [["xax2", is(cs[2]=1), "on the x-axis"], ["yax2", is(cs[2]=2), "on the y-axis"], ["zax2", is(cs[2]=3), "on the z-axis"], ["xy2", is(cs[2]=4), "in the xy-plane, not on an axis"], ["yz2", is(cs[2]=5), "in the yz-plane, not on an axis"], ["xz2", is(cs[2]=6), "in the xz-plane, not on an axis"], ["none2", is(cs[2]=7), "in no coordinate plane"]];
ta2: first(mcq_correct(opt2)); dg2: opt2[g2][1];
gw2: if c2 = 7 or g2 = 7 then opt2[5][1] else opt2[7][1];
p3: pts[3]; c3: cs[3]; g3: dgof[c3];
opt3: [["xax3", is(cs[3]=1), "on the x-axis"], ["yax3", is(cs[3]=2), "on the y-axis"], ["zax3", is(cs[3]=3), "on the z-axis"], ["xy3", is(cs[3]=4), "in the xy-plane, not on an axis"], ["yz3", is(cs[3]=5), "in the yz-plane, not on an axis"], ["xz3", is(cs[3]=6), "in the xz-plane, not on an axis"], ["none3", is(cs[3]=7), "in no coordinate plane"]];
ta3: first(mcq_correct(opt3)); dg3: opt3[g3][1];
gw3: if c3 = 7 or g3 = 7 then opt3[5][1] else opt3[7][1];
p4: pts[4]; c4: cs[4]; g4: dgof[c4];
opt4: [["xax4", is(cs[4]=1), "on the x-axis"], ["yax4", is(cs[4]=2), "on the y-axis"], ["zax4", is(cs[4]=3), "on the z-axis"], ["xy4", is(cs[4]=4), "in the xy-plane, not on an axis"], ["yz4", is(cs[4]=5), "in the yz-plane, not on an axis"], ["xz4", is(cs[4]=6), "in the xz-plane, not on an axis"], ["none4", is(cs[4]=7), "in no coordinate plane"]];
ta4: first(mcq_correct(opt4)); dg4: opt4[g4][1];
gw4: if c4 = 7 or g4 = 7 then opt4[5][1] else opt4[7][1];

feedbackvariables.text:
ch: first(sublist_indices(opt1, lambda([o], is(o[1] = ans1))));
zs: [[2,3],[1,3],[1,2],[3],[1],[2],[]][ch];
bad: sublist(zs, lambda([t], is(p1[t] # 0)));
ext: sublist([1,2,3], lambda([t], is(not member(t, zs)) and is(p1[t] = 0)));
bm: if bad = [] then 0 else bad[1]; em: if ext = [] then 0 else ext[1];
bv: if bm > 0 then p1[bm] else 0;

