bm: if bad = [] then 0 else bad[1]; em: if ext = [] then 0 else ext[1];
bv: if bm > 0 then p3[bm] else 0;

ch: first(sublist_indices(opt4, lambda([o], is(o[1] = ans4))));
zs: [[2,3],[1,3],[1,2],[3],[1],[2],[]][ch];
bad: sublist(zs, lambda([t], is(p4[t] # 0)));
